explanation.code:
class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

acc = Account("Sam")
acc.deposit(50)
print(acc.balance)  # 50

examples.code:
class Account:
    def __init__(self, balance=0):
        self.balance = balance

class Savings(Account):
    def add_interest(self):
        self.balance *= 1.05

saver = Savings(100)
saver.add_interest()
print(saver.balance)

